import{_ as e,o as i,c as l,a0 as t}from"./chunks/framework.DqMqoJl9.js";const o="/assets/1_1.B5SiXXtd.png",u=JSON.parse('{"title":"版本","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/3-synopsis.md","filePath":"webpack/3-synopsis.md","lastUpdated":1791573371000}'),r={name:"webpack/3-synopsis.md"};function s(p,a,n,c,d,_){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1 概述&quot;">​</a></h2><p>本质上，webpack 是一个现代 JavaScript 应用程序的静态模块打包器(module bundler)。当 webpack 处理应用程序时，它会递归地构建一个依赖关系图(dependency graph)，其中包含应用程序需要的每个模块，然后将所有这些模块打包成一个或多个 bundle</p><p><img src="'+o+'" alt=""></p><h2 id="_2-版本更迭" tabindex="-1">2 版本更迭 <a class="header-anchor" href="#_2-版本更迭" aria-label="Permalink to &quot;2 版本更迭&quot;">​</a></h2><ul><li>webpack v1.0.0 -- 2014.02.20</li><li>webpack v2.2.0 -- 2017.01.18</li><li>webpack v3.0.0 -- 2017.06.19</li><li>webpack v4.0.0 -- 2018.02.26</li><li>webpack v4.41.6 -- 当前</li></ul><h2 id="_3-功能进化" tabindex="-1">3 功能进化 <a class="header-anchor" href="#_3-功能进化" aria-label="Permalink to &quot;3 功能进化&quot;">​</a></h2><p>v1:</p><ul><li>编译、打包</li><li>模块热更新</li><li>代码分割</li><li>文件处理</li></ul><p>v2:</p><ul><li>tree shaking(会去除引入了但没用到的代码，打包后体积更小)</li><li>ES Module(v1 版本需要 babel)</li><li>动态 import</li></ul><p>v3:</p><ul><li>scope hoisting(作用域提升)(提高打包后代码的性能)(老版本打包后的模块都包裹在一个单独的闭包中，这对性能有损耗)(作用域提升会将所有模块的作用域提到单一的一个闭包中)</li><li>magic comments(配合动态 improt 使用)(可以指定打包后的文件名)</li></ul>',13)])])}const b=e(r,[["render",s]]);export{u as __pageData,b as default};
